"""Build departure boards from a timetable feed. See /app/docs."""
import csv
import io
import json
import os
import sys
from datetime import date, datetime, timedelta, timezone
from zoneinfo import ZoneInfo


def read_csv(directory, name):
    path = os.path.join(directory, name)
    if not os.path.exists(path):
        return []
    with open(path, "rb") as f:
        text = f.read().decode("utf-8-sig")
    reader = csv.reader(io.StringIO(text, newline=""))
    header = None
    rows = []
    for raw in reader:
        if not raw or all(c.strip() == "" for c in raw):
            continue
        if header is None:
            header = [c.strip() for c in raw]
            continue
        row = {}
        for i, h in enumerate(header):
            row[h] = raw[i].strip() if i < len(raw) else ""
        rows.append(row)
    return rows


def parse_time(s):
    h, m, sec = s.split(":")
    return int(h) * 3600 + int(m) * 60 + int(sec)


def parse_date(s):
    return date(int(s[0:4]), int(s[4:6]), int(s[6:8]))


WEEKDAYS = ["monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday"]


def main():
    indir, outfile = sys.argv[1], sys.argv[2]
    with open(os.path.join(indir, "request.json"), "rb") as f:
        request = json.loads(f.read().decode("utf-8-sig"))
    dates = sorted({date.fromisoformat(d) for d in request["service_dates"]})

    agencies = read_csv(indir, "agency.txt")
    stops = {r["stop_id"]: r for r in read_csv(indir, "stops.txt")}
    routes = {r["route_id"]: r for r in read_csv(indir, "routes.txt")}
    trips = {r["trip_id"]: r for r in read_csv(indir, "trips.txt")}
    calendar = {r["service_id"]: r for r in read_csv(indir, "calendar.txt")}
    cal_dates = {}
    for r in read_csv(indir, "calendar_dates.txt"):
        cal_dates[(r["service_id"], r["date"])] = r["exception_type"]
    freqs = {}
    for r in read_csv(indir, "frequencies.txt"):
        freqs.setdefault(r["trip_id"], []).append(r)
    agency_tz = {a["agency_id"]: ZoneInfo(a["agency_timezone"]) for a in agencies}
    default_tz = agencies[0]["agency_timezone"] if agencies else "UTC"

    st_by_trip = {}
    for r in read_csv(indir, "stop_times.txt"):
        r["_seq"] = int(r["stop_sequence"])
        st_by_trip.setdefault(r["trip_id"], []).append(r)

    # board stops
    board_stops = []
    for sid, s in stops.items():
        lt = s.get("location_type", "") or "0"
        if lt == "1" or (lt == "0" and not s.get("parent_station", "")):
            board_stops.append(sid)

    def board_of(stop_id):
        s = stops[stop_id]
        p = s.get("parent_station", "")
        return p if p else stop_id

    def board_tz_name(sid):
        return stops[sid].get("stop_timezone", "") or default_tz

    def runs(service_id, d):
        ex = cal_dates.get((service_id, d.strftime("%Y%m%d")))
        if ex == "1":
            return True
        if ex == "2":
            return False
        c = calendar.get(service_id)
        if not c:
            return False
        if not (parse_date(c["start_date"]) <= d <= parse_date(c["end_date"])):
            return False
        return c.get(WEEKDAYS[d.weekday()], "") == "1"

    # Precompute per-trip stop data (independent of date)
    trip_info = {}
    for tid, rows in st_by_trip.items():
        if tid not in trips:
            continue
        rows.sort(key=lambda r: r["_seq"])
        times = []
        for r in rows:
            t = r.get("departure_time", "") or r.get("arrival_time", "")
            times.append(parse_time(t) if t else None)
        n = len(rows)
        known = [i for i in range(n) if times[i] is not None]
        for a, b in zip(known, known[1:]):
            steps = b - a
            for i in range(a + 1, b):
                times[i] = times[a] + (times[b] - times[a]) * (i - a) // steps
        trip = trips[tid]
        if trip.get("trip_headsign", ""):
            default_head = trip["trip_headsign"]
        else:
            last = stops[rows[-1]["stop_id"]]
            p = last.get("parent_station", "")
            default_head = stops[p]["stop_name"] if p and p in stops else last["stop_name"]
        route = routes[trip["route_id"]]
        label = route.get("route_short_name", "") or route.get("route_long_name", "")
        deps = []  # (time, stop_id, headsign)
        for i, r in enumerate(rows):
            if i == n - 1 or r.get("pickup_type", "") == "1":
                continue
            head = r.get("stop_headsign", "") or default_head
            deps.append((times[i], r["stop_id"], head))
        trip_info[tid] = (label, route["agency_id"], times[0], deps)

    boards = {}
    for sid in board_stops:
        for d in dates:
            boards[(sid, d)] = []

    def fmt(dt):
        return dt.isoformat()

    for d in dates:
        for tid, (label, agency, t0, deps) in trip_info.items():
            trip = trips[tid]
            if not runs(trip["service_id"], d):
                continue
            tz = agency_tz[agency]
            noon = datetime(d.year, d.month, d.day, 12, tzinfo=tz)
            origin = noon.astimezone(timezone.utc) - timedelta(hours=12)

            entries = []  # (kind, secs, until_secs, headway, stop_id, head)
            if tid in freqs:
                for w in freqs[tid]:
                    start = parse_time(w["start_time"])
                    end = parse_time(w["end_time"])
                    hw = int(w["headway_secs"])
                    if start >= end:
                        continue
                    starts = list(range(start, end, hw))
                    exact = w.get("exact_times", "") == "1"
                    for (t, stop_id, head) in deps:
                        off = t - t0
                        if exact:
                            for s in starts:
                                entries.append(("scheduled", s + off, None, None, stop_id, head))
                        else:
                            entries.append(("interval", starts[0] + off, starts[-1] + off, hw, stop_id, head))
            else:
                for (t, stop_id, head) in deps:
                    entries.append(("scheduled", t, None, None, stop_id, head))

            for kind, secs, until, hw, stop_id, head in entries:
                b = board_of(stop_id)
                if (b, d) not in boards:
                    continue
                btz = ZoneInfo(board_tz_name(b))
                inst = origin + timedelta(seconds=secs)
                local = inst.astimezone(btz)
                plat = stops[stop_id].get("platform_code", "") or None
                un = None
                if until is not None:
                    un = fmt((origin + timedelta(seconds=until)).astimezone(btz))
                boards[(b, d)].append((inst, label, head, tid, plat, {
                    "kind": kind,
                    "time": fmt(local),
                    "until": un,
                    "headway_secs": hw,
                    "route": label,
                    "headsign": head,
                    "trip": tid,
                    "platform": plat,
                    "agency": agency,
                }))

    out_boards = []
    for (sid, d) in sorted(boards, key=lambda k: (k[0], k[1])):
        items = boards[(sid, d)]
        items.sort(key=lambda x: (x[0], x[1], x[2], x[3], (0, "") if x[4] is None else (1, x[4])))
        out_boards.append({
            "stop_id": sid,
            "name": stops[sid]["stop_name"],
            "timezone": board_tz_name(sid),
            "service_date": d.isoformat(),
            "departures": [x[5] for x in items],
        })
    result = {"service_dates": [d.isoformat() for d in dates], "boards": out_boards}
    with open(outfile, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=1)


if __name__ == "__main__":
    main()
